import json

d = {1: (2, 3), "x": None}
s = json.dumps(d)
print(s)   # {"1": [2, 3], "x": null}
print(json.loads(s))
# {'1': [2, 3], 'x': None}

import json

class Schueler:
    def __init__(self, name, klasse):
        self.name = name
        self.klasse = klasse

    def to_dict(self):
        return {"name": self.name,
                "klasse": self.klasse}

    @classmethod
    def from_dict(cls, d):
        return cls(d["name"], d["klasse"])

s = Schueler("Lea", "3AHIF")
with open("lea.json", "w",
          encoding="utf-8") as f:
    json.dump(s.to_dict(), f)

with open("lea.json",
          encoding="utf-8") as f:
    s2 = Schueler.from_dict(json.load(f))
print(s2.name, s2.klasse)  # Lea 3AHIF

